#!/usr/bin/env python

import math
import operator

import numpy as np
from multiprocessing import Pool, cpu_count

'''
All of these algorithms have been taken from the paper:
Trotmam et al, Improvements to BM25 and Language Models Examined

Here we implement all the BM25 variations mentioned.
'''


class BM25:
    def __init__(self, corpus, tokenizer=None):
        self.corpus_size = 0
        self.avgdl = 0
        self.doc_freqs = []
        self.idf = {}
        self.doc_len = []
        self.tokenizer = tokenizer

        if tokenizer:
            corpus = self._tokenize_corpus(corpus)

        nd = self._initialize(corpus)
        self._calc_idf(nd)

    def _initialize(self, corpus):
        nd = {}
        num_doc = 0
        for document in corpus:
            self.doc_len.append(len(document))
            num_doc += len(document)

            frequencies = {}
            for word in document:
                if word not in frequencies:
                    frequencies[word] = 0
                frequencies[word] += 1
            self.doc_freqs.append(frequencies)

            for word in frequencies:
                nd[word] = nd.get(word, 0) + 1

            self.corpus_size += 1

        if self.corpus_size:
            self.avgdl = num_doc / self.corpus_size
        else:
            self.avgdl = 0.0
        return nd

    def _tokenize_corpus(self, corpus):
        pool = Pool(cpu_count())
        tokenized_corpus = pool.map(self.tokenizer, corpus)
        return tokenized_corpus

    def _length_norm(self, doc_len=None):
        if doc_len is None:
            doc_len = np.asarray(self.doc_len, dtype=float)
        else:
            doc_len = np.asarray(doc_len, dtype=float)
        if self.avgdl > 0:
            ratio = doc_len / self.avgdl
        else:
            ratio = np.zeros_like(doc_len)
        return 1.0 - self.b + self.b * ratio

    def _validate_doc_ids(self, doc_ids):
        try:
            iterator = iter(doc_ids)
        except TypeError as exc:
            raise TypeError('doc_ids must be an iterable of integers') from exc

        validated = []
        for doc_id in iterator:
            try:
                idx = operator.index(doc_id)
            except TypeError as exc:
                raise TypeError('document indices must be integers') from exc
            if idx < 0 or idx >= self.corpus_size:
                raise IndexError('document index out of range')
            validated.append(idx)
        return validated

    def _calc_idf(self, nd):
        raise NotImplementedError()

    def get_scores(self, query):
        raise NotImplementedError()

    def get_batch_scores(self, query, doc_ids):
        raise NotImplementedError()

    def get_top_n(self, query, documents, n=5):
        assert self.corpus_size == len(documents), 'The documents given do not match the index corpus!'

        if n <= 0:
            return []

        scores = self.get_scores(query)
        top_n = np.argsort(scores)[::-1][:n]
        return [documents[i] for i in top_n]


class BM25Okapi(BM25):
    def __init__(self, corpus, tokenizer=None, k1=1.5, b=0.75, epsilon=0.25):
        self.k1 = k1
        self.b = b
        self.epsilon = epsilon
        super().__init__(corpus, tokenizer)

    def _calc_idf(self, nd):
        idf_sum = 0.0
        negative_idfs = []
        for word, freq in nd.items():
            idf = math.log(self.corpus_size - freq + 0.5) - math.log(freq + 0.5)
            self.idf[word] = idf
            idf_sum += idf
            if idf < 0:
                negative_idfs.append(word)
        self.average_idf = idf_sum / len(self.idf) if self.idf else 0.0

        eps = self.epsilon * self.average_idf
        for word in negative_idfs:
            self.idf[word] = eps

    def get_scores(self, query):
        score = np.zeros(self.corpus_size, dtype=float)
        if self.corpus_size == 0 or self.avgdl == 0:
            return score

        length_norm = self._length_norm()
        for q in query:
            q_freq = np.asarray([(doc.get(q) or 0) for doc in self.doc_freqs], dtype=float)
            denominator = q_freq + self.k1 * length_norm
            term = np.divide(
                q_freq * (self.k1 + 1.0),
                denominator,
                out=np.zeros_like(q_freq, dtype=float),
                where=denominator != 0,
            )
            score += (self.idf.get(q) or 0) * term
        return score

    def get_batch_scores(self, query, doc_ids):
        doc_ids = self._validate_doc_ids(doc_ids)
        if self.corpus_size == 0 or self.avgdl == 0:
            return [0.0] * len(doc_ids)

        score = np.zeros(len(doc_ids), dtype=float)
        doc_len = np.asarray(self.doc_len, dtype=float)[doc_ids]
        length_norm = self._length_norm(doc_len)
        for q in query:
            q_freq = np.asarray([(self.doc_freqs[di].get(q) or 0) for di in doc_ids], dtype=float)
            denominator = q_freq + self.k1 * length_norm
            term = np.divide(
                q_freq * (self.k1 + 1.0),
                denominator,
                out=np.zeros_like(q_freq, dtype=float),
                where=denominator != 0,
            )
            score += (self.idf.get(q) or 0) * term
        return score.tolist()


class BM25L(BM25):
    def __init__(self, corpus, tokenizer=None, k1=1.5, b=0.75, delta=0.5):
        self.k1 = k1
        self.b = b
        self.delta = delta
        super().__init__(corpus, tokenizer)

    def _calc_idf(self, nd):
        for word, freq in nd.items():
            idf = math.log(self.corpus_size + 1) - math.log(freq + 0.5)
            self.idf[word] = idf

    def get_scores(self, query):
        score = np.zeros(self.corpus_size, dtype=float)
        if self.corpus_size == 0 or self.avgdl == 0:
            return score

        length_norm = self._length_norm()
        for q in query:
            q_freq = np.asarray([(doc.get(q) or 0) for doc in self.doc_freqs], dtype=float)
            ctd = np.divide(
                q_freq,
                length_norm,
                out=np.zeros_like(q_freq, dtype=float),
                where=length_norm != 0,
            )
            numerator = (self.k1 + 1.0) * (ctd + self.delta)
            denominator = self.k1 + ctd + self.delta
            term = np.divide(
                numerator,
                denominator,
                out=np.zeros_like(q_freq, dtype=float),
                where=denominator != 0,
            )
            score += (self.idf.get(q) or 0) * term
        return score

    def get_batch_scores(self, query, doc_ids):
        doc_ids = self._validate_doc_ids(doc_ids)
        if self.corpus_size == 0 or self.avgdl == 0:
            return [0.0] * len(doc_ids)

        score = np.zeros(len(doc_ids), dtype=float)
        doc_len = np.asarray(self.doc_len, dtype=float)[doc_ids]
        length_norm = self._length_norm(doc_len)
        for q in query:
            q_freq = np.asarray([(self.doc_freqs[di].get(q) or 0) for di in doc_ids], dtype=float)
            ctd = np.divide(
                q_freq,
                length_norm,
                out=np.zeros_like(q_freq, dtype=float),
                where=length_norm != 0,
            )
            numerator = (self.k1 + 1.0) * (ctd + self.delta)
            denominator = self.k1 + ctd + self.delta
            term = np.divide(
                numerator,
                denominator,
                out=np.zeros_like(q_freq, dtype=float),
                where=denominator != 0,
            )
            score += (self.idf.get(q) or 0) * term
        return score.tolist()


class BM25Plus(BM25):
    def __init__(self, corpus, tokenizer=None, k1=1.5, b=0.75, delta=1):
        self.k1 = k1
        self.b = b
        self.delta = delta
        super().__init__(corpus, tokenizer)

    def _calc_idf(self, nd):
        for word, freq in nd.items():
            idf = math.log(self.corpus_size + 1) - math.log(freq)
            self.idf[word] = idf

    def get_scores(self, query):
        score = np.zeros(self.corpus_size, dtype=float)
        if self.corpus_size == 0 or self.avgdl == 0:
            return score

        length_norm = self._length_norm()
        for q in query:
            q_freq = np.asarray([(doc.get(q) or 0) for doc in self.doc_freqs], dtype=float)
            denominator = self.k1 * length_norm + q_freq
            fraction = np.divide(
                q_freq * (self.k1 + 1.0),
                denominator,
                out=np.zeros_like(q_freq, dtype=float),
                where=denominator != 0,
            )
            score += (self.idf.get(q) or 0) * (self.delta + fraction)
        return score

    def get_batch_scores(self, query, doc_ids):
        doc_ids = self._validate_doc_ids(doc_ids)
        if self.corpus_size == 0 or self.avgdl == 0:
            return [0.0] * len(doc_ids)

        score = np.zeros(len(doc_ids), dtype=float)
        doc_len = np.asarray(self.doc_len, dtype=float)[doc_ids]
        length_norm = self._length_norm(doc_len)
        for q in query:
            q_freq = np.asarray([(self.doc_freqs[di].get(q) or 0) for di in doc_ids], dtype=float)
            denominator = self.k1 * length_norm + q_freq
            fraction = np.divide(
                q_freq * (self.k1 + 1.0),
                denominator,
                out=np.zeros_like(q_freq, dtype=float),
                where=denominator != 0,
            )
            score += (self.idf.get(q) or 0) * (self.delta + fraction)
        return score.tolist()

